    "content": "session: Return policy RAG — Azure AI Foundry evaluation\ndataset:\n  id: cases\n  path: cases.jsonl\n# cases.jsonl:\n# {\"userQuery\": \"What's your return policy?\"}\n# {\"userQuery\": \"Can I return opened items?\"}\ndescription: |\n  Same spec as rag-groundedness.yaml, but evaluations route through Azure AI\n  Foundry Evaluation. Run with: abslang run ... --adapter azure\n\nbehaviors:\n  - id: user_asks\n    actor: user\n    action: says\n    content: \"{{cases.userQuery}}\"\n\n  - id: kb_call\n    actor: assistant\n    action: calls\n    target: Knowledge Base\n\n  - id: kb_result\n    actor: tool\n    action: responds\n    target: Knowledge Base\n\n  - id: answer\n    actor: assistant\n    action: informs\n    evaluations:\n      - type: Groundedness\n        adapter: azure\n        query: user_asks.says\n        context: kb_result.responds\n        response: self\n        threshold: 0.8\n      - type: Relevance\n        adapter: azure\n        query: user_asks.says\n        response: self\n        threshold: 0.7\n      - type: Coherence\n        adapter: azure\n        response: self\n        threshold: 0.7\n      - type: custom\n        id: azure.tool_call_accuracy\n        adapter: azure\n        threshold: 0.6\n\nevaluations:\n  - type: sequence\n    order:\n      - { actor: assistant, action: calls, target: \"Knowledge Base\" }\n      - { actor: assistant, action: informs }"
